// @generated by:gauntlet run:godseye-e08-independent-gauntlet

import { randomUUID } from "node:crypto";
import { schema } from "@godseye/store";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { IncidentEngine, type IncidentNotifier } from "../packages/core/src/incidents.js";
import { controlled } from "./helpers/agents-fixture.js";
import {
  type E08ObservabilityFixture,
  e08ObservabilityFixture,
} from "./helpers/e08-observability.js";
import { required } from "./helpers/e08-values.js";

describe("E08 existing incident engine and durable notification effects", () => {
  let f: E08ObservabilityFixture, detectorFails: boolean;
  beforeEach(async () => {
    f = await e08ObservabilityFixture();
    detectorFails = false;
    await f.register();
  });
  afterEach(async () => {
    await f.store.close();
  });
  const engine = (notifier?: IncidentNotifier) =>
    new IncidentEngine(f.store, {
      now: f.clock.now,
      notifier,
      sources: {
        backups: (actor) => f.infrastructure.recovery.backups(actor),
        rotations: (actor) => f.infrastructure.rotation.overview(actor),
        observability: async (actor) => {
          if (detectorFails) throw new Error("Synthetic detector outage");
          return f.engine.incidentFindings(actor);
        },
      },
    });
  const raise = async () =>
    required((await engine().evaluate(f.freshOwner(), randomUUID())).incidents[0]);

  it("T-AC-812 does not clear an active health incident when its detector fails", async () => {
    const original = await raise();
    detectorFails = true;
    const later = (await engine().evaluate(f.freshOwner(), randomUUID())).incidents.find(
      (row) => row.id === original.id,
    );
    expect(later).toMatchObject({ state: "open", resolution: null, reason: "TELEMETRY_MISSING" });
  });

  it("T-AC-813 commits a single delivery claim before crossing concurrent notifier boundaries", async () => {
    const incident = await raise(),
      entered = controlled<void>(),
      release = controlled<void>();
    let calls = 0,
      claimed = false,
      identity = "";
    const notifier: IncidentNotifier = {
      async notify(view, context) {
        calls++;
        identity = context?.idempotencyKey ?? "";
        const [out] = await f.store.db.select().from(schema.incidentOutbox);
        claimed = out?.state === "delivering" && out.incidentId === view.id && out.attempts === 1;
        entered.resolve();
        await release.promise;
        return { state: "notified", receipt: "synthetic-delivery-ack" };
      },
    };
    const first = engine(notifier).deliver();
    await entered.promise;
    await engine({ notify: notifier.notify }).deliver();
    release.resolve();
    await first;
    expect({ calls, claimed, identity }).toEqual({
      calls: 1,
      claimed: true,
      identity: `incident:${incident.id}`,
    });
    expect((await engine().overview(f.freshOwner())).incidents[0]?.delivery).toMatchObject({
      state: "notified",
      attempts: 1,
    });
  });

  it("T-AC-813 preserves unknown delivery after crash following physical send and never blindly retries", async () => {
    await raise();
    let sends = 0;
    const notifier: IncidentNotifier = {
      async notify() {
        sends++;
        throw new Error("Synthetic delivery happened, acknowledgement lost");
      },
    };
    await engine(notifier).deliver();
    for (let index = 0; index < 4; index++) await engine({ notify: notifier.notify }).deliver();
    expect(sends).toBe(1);
    expect((await engine().overview(f.freshOwner())).incidents[0]?.delivery).toMatchObject({
      state: "unknown",
      attempts: 1,
    });
  });

  it("T-AC-813 retries definitive rejection only within a finite bound", async () => {
    await raise();
    let sends = 0;
    const notifier: IncidentNotifier = {
      async notify() {
        sends++;
        return { state: "failed" };
      },
    };
    for (let index = 0; index < 6; index++) await engine({ notify: notifier.notify }).deliver();
    expect(sends).toBe(3);
    expect((await engine().overview(f.freshOwner())).incidents[0]?.delivery).toMatchObject({
      state: "failed",
      attempts: 3,
    });
  });

  it("T-AC-813 suppresses acknowledged or muted notifications and resumes only after mute expiry", async () => {
    const original = await raise();
    let sends = 0;
    const notifier: IncidentNotifier = {
      async notify() {
        sends++;
        return { state: "notified" };
      },
    };
    const muted = await engine().mute(
      f.freshOwner(),
      original.id,
      {
        expectedRevision: original.revision,
        until: new Date(f.clock.now().getTime() + 5000).toISOString(),
      },
      randomUUID(),
    );
    await engine(notifier).deliver();
    expect(sends).toBe(0);
    f.clock.advance(5001);
    await engine(notifier).deliver();
    expect(sends).toBe(1);
    await expect(
      engine().acknowledge(
        f.freshOwner(),
        original.id,
        { expectedRevision: original.revision },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ code: "REVISION_CONFLICT" });
    expect(muted.muted).toBe(true);
  });

  it("T-AC-814 keeps notification delivery explicitly unconfigured without a trusted adapter", async () => {
    const original = await raise();
    await engine().deliver();
    expect((await engine().overview(f.freshOwner())).incidents[0]).toMatchObject({
      id: original.id,
      delivery: { state: "unconfigured", attempts: 0 },
    });
    expect(await f.store.db.select().from(schema.incidentOutbox)).toHaveLength(0);
  });
});
